  <section class="workbench" aria-labelledby="workbench-title">
    <header class="workbench__header">
      <div>
        <p class="eyebrow">Party Land vertical slice</p>
        <h1 id="workbench-title">Pinball Fantasies <span>HD</span></h1>
      </div>
      <p class="development-badge" role="status">
        Playable mechanics slice · parity and final HD incomplete
      </p>
    </header>

    <div class="workbench__body">
      <div class="playfield-shell">
        <canvas
          id="party-workbench-canvas"
          tabindex="-1"
          aria-label="Interactive Party Land HD candidate over the ${pe} simulation kernel"
        ></canvas>
        <button
          class="plunger-zone"
          id="plunger-zone"
          type="button"
          aria-label="Hold or drag down to pull the plunger"
        >
          <span>Pull</span>
        </button>
      </div>

      <aside class="telemetry" aria-labelledby="telemetry-title">
        <p class="eyebrow">Live deterministic state</p>
        <h2 id="telemetry-title">Kernel telemetry</h2>
        <button
          class="sound-toggle"
          id="sound-toggle"
          type="button"
          aria-pressed="true"
        >
          Recreated sound: on
        </button>
        <button
          class="diagnostics-toggle"
          id="diagnostics-toggle"
          type="button"
          aria-pressed="false"
        >
          Diagnostics: off
        </button>
        <label class="lamp-diagnostic">
          <span>Lamp QA</span>
          <select id="lamp-diagnostic">
            <option value="gameplay">Gameplay state</option>
            <option value="all-on">All 51 on</option>
            <option value="all-off">All 51 off</option>
          </select>
        </label>
        <dl>
          <div><dt>Phase</dt><dd id="state-phase">Starting</dd></div>
          <div><dt>Player / ball</dt><dd id="state-player">1 / 1</dd></div>
          <div><dt>Serve display</dt><dd id="state-serve-display">Starting</dd></div>
          <div><dt>Score</dt><dd id="state-score">0</dd></div>
          <div><dt>Live HUD buffer</dt><dd id="state-live-hud">not rendered</dd></div>
          <div><dt>Ball</dt><dd id="state-ball">302, 534</dd></div>
          <div><dt>Velocity</dt><dd id="state-velocity">0, 0</dd></div>
          <div><dt>Camera</dt><dd id="state-camera">0</dd></div>
          <div><dt>Services</dt><dd id="state-services">0</dd></div>
          <div><dt>Frame backlog</dt><dd id="state-backlog">0</dd></div>
          <div><dt>Mean FPS</dt><dd id="state-fps">—</dd></div>
          <div><dt>P95 frame</dt><dd id="state-frame-p95">—</dd></div>
          <div><dt>P95 render</dt><dd id="state-render-p95">—</dd></div>
          <div><dt>Render scale</dt><dd id="state-render-scale">—</dd></div>
          <div><dt>Observed path</dt><dd id="state-path">serve</dd></div>
        </dl>
        <p class="telemetry__note">
          The workbench renders a newly generated HD base candidate with
          diagnostics hidden by default, clean-room flipper frames, and
          event-driven device flashes. The optional diagnostics view adds
          public coordinates and the provisional independently authored
          collision draft. Flippers, launch, camera, fixed-point
          ball state, physical bumper and sling scoring, cue timing, input
          release, and end-ball transitions are live. Final art correction,
          foreground geometry, remaining rule paths, exact lamp/flasher
          visual matching, final state artwork, and full-table parity remain
          incomplete.
        </p>
      </aside>
    </div>

    <div
      class="post-game-actions"
      id="post-game-actions"
      aria-label="Game over actions"
      hidden
    >
      <button id="play-again" type="button">Play again</button>
      <button id="return-table-menu" type="button">Table menu</button>
      <span>F1-F8 starts a new game / Escape returns to tables</span>
    </div>

    <div class="control-deck" aria-label="Pinball controls">
      <button type="button" data-control="left-flipper">
        <span>Left</span><kbd>Z</kbd><kbd>←</kbd>
      </button>
      <button type="button" data-control="nudge">
        <span>Nudge</span><kbd>X</kbd><kbd>↑</kbd>
      </button>
      <button type="button" data-control="plunger">
        <span>Plunger</span><kbd>Space</kbd><kbd>↓</kbd>
      </button>
      <button type="button" data-control="right-flipper">
        <span>Right</span><kbd>/</kbd><kbd>→</kbd>
      </button>
    </div>

    <section
      class="table-menu"
      id="table-menu"
      aria-labelledby="table-menu-title"
      hidden
    >
      <p class="eyebrow">Original four-table set</p>
      <h2 id="table-menu-title">Choose a table</h2>
      <div class="table-menu__grid">
        <button type="button" data-start-party="1">
          <strong>Party Land</strong>
          <span>Start 1 player</span>
        </button>
        <button type="button" data-start-speed>
          <strong>Speed Devils</strong>
          <span>Playable mechanics preview</span>
        </button>
        <button type="button" data-start-gameshow>
          <strong>Billion Dollar Gameshow</strong>
          <span>Playable mechanics preview</span>
        </button>
        <button type="button" data-start-stones>
          <strong>Stones 'N Bones</strong>
          <span>First playable slice</span>
        </button>
      </div>
      <div class="table-menu__players" aria-label="Party Land player count">
        ${Array.from({length:8},(e,t)=>`<button type="button" data-start-party="${String(t+1)}">F${String(t+1)} / ${String(t+1)}P</button>`).join("")}
      </div>
      <div
        class="global-scores"
        id="party-global-scores"
        aria-label="Party Land global top ten"
      ></div>
    </section>

    <footer class="workbench__footer">
      <p>
        Current checkpoint: canonical 19-group manifest, all five physical
        holes, all ten source-ordered high contacts with raw Skyride gate
        state, corrected Toucher-to-Arcade arming, exact
        drain/payout/reset lifecycle, provisional full static material,
        authored shooter route, flipper collision, live scoring devices,
        individual QA for all 51 renderable dynamic nodes, source-ordered
        serve-status/modal mailbox composition, exact pause ownership, and the
        original Match decision/presentation/replay, game-over
        ranking/name-entry continuation, two-pass post-game player cards, and
        source-priority restart/table-menu boundaries.
      </p>
      <p id="runtime-status" aria-live="polite">Initializing browser adapter…</p>
    </footer>
  </section>
